package main

import (
	"net/http"
	"net/http/httptest"
	"net/url"
	"testing"
)

// functional unittests
func TestFuncComposeAuthorizationLinkReturnsValidURL(t *testing.T) {
	respHandler := httptest.NewRecorder()
	reqContext := httptest.NewRequest("GET", "/login", nil)
	activeSession := &http.Cookie{Name: "session_id", Value: "test-session-123"}

	authLink, err := ComposeAuthorizationLink("/dashboard", activeSession, respHandler, reqContext)

	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
	if authLink == "" {
		t.Fatal("expected non-empty auth link")
	}
	linkURL, err := url.Parse(authLink)
	if err != nil {
		t.Fatalf("expected valid URL, got parse error: %v", err)
	}
	if linkURL.Host != "provider.com" {
		t.Errorf("expected host provider.com, got %s", linkURL.Host)
	}
}

func TestFuncComposeAuthorizationLinkContainsRequiredParams(t *testing.T) {
	respHandler := httptest.NewRecorder()
	reqContext := httptest.NewRequest("GET", "/login", nil)
	activeSession := &http.Cookie{Name: "session_id", Value: "test-session-456"}

	authLink, err := ComposeAuthorizationLink("/profile", activeSession, respHandler, reqContext)

	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
	linkURL, _ := url.Parse(authLink)
	authParams := linkURL.Query()

	if authParams.Get("client_id") == "" {
		t.Error("expected client_id parameter")
	}
	if authParams.Get("redirect_uri") == "" {
		t.Error("expected redirect_uri parameter")
	}
	if authParams.Get("response_type") == "" {
		t.Error("expected response_type parameter")
	}
	if authParams.Get("state") == "" {
		t.Error("expected state parameter")
	}
}

