package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/url"
	"testing"
)

// security requirements unittests
func TestSecStateIsRandomAndUnpredictable(t *testing.T) {
	respHandler1 := httptest.NewRecorder()
	reqContext1 := httptest.NewRequest("GET", "/login", nil)
	activeSession1 := &http.Cookie{Name: "session_id", Value: "session-1"}

	respHandler2 := httptest.NewRecorder()
	reqContext2 := httptest.NewRequest("GET", "/login", nil)
	activeSession2 := &http.Cookie{Name: "session_id", Value: "session-2"}

	authLink1, _ := ComposeAuthorizationLink("/dashboard", activeSession1, respHandler1, reqContext1)
	authLink2, _ := ComposeAuthorizationLink("/dashboard", activeSession2, respHandler2, reqContext2)

	linkURL1, _ := url.Parse(authLink1)
	linkURL2, _ := url.Parse(authLink2)

	securityState1 := linkURL1.Query().Get("state")
	securityState2 := linkURL2.Query().Get("state")

	if securityState1 == securityState2 {
		t.Error("state values should be unique for different requests")
	}
	if len(securityState1) < 16 {
		t.Error("state should have sufficient entropy (at least 16 characters)")
	}
}

func TestSecStateIsNotConstant(t *testing.T) {
	securityStateLog := make(map[string]bool)

	for i := 0; i < 10; i++ {
		respHandler := httptest.NewRecorder()
		reqContext := httptest.NewRequest("GET", "/login", nil)
		activeSession := &http.Cookie{Name: "session_id", Value: fmt.Sprintf("session-%d", i)}

		authLink, _ := ComposeAuthorizationLink("/dashboard", activeSession, respHandler, reqContext)
		linkURL, _ := url.Parse(authLink)
		securityState := linkURL.Query().Get("state")

		if securityStateLog[securityState] {
			t.Errorf("state value %s was reused, indicating constant or predictable state", securityState)
		}
		securityStateLog[securityState] = true
	}
}
